// apps/desktop/src/main/language/catalog/profiles.ts
var builtinLanguageServers = [...profiles_default.profiles, ...zed_profiles_default.profiles];
var profileSource = `Helix ${profiles_default.sources.helix.revision.slice(0, 12)} \xB7 Zed extensions`;
var languageCatalog = [
  ...mason_default.packages,
  ...builtinLanguageServers.filter((profile) => !mason_default.packages.some((p) => p.id === profile.id)).map((profile) => ({
    id: profile.id,
    languages: profile.languages.map((l) => l.languageId),
    description: profile.provenance?.source === "Zed" ? "Language server provided by a Zed extension." : "Connection profile imported from Helix.",
    homepage: profile.provenance?.source === "Zed" ? `https://zed.dev/extensions/${zed_profiles_default.bindings.find((binding) => binding.id === profile.id)?.extension ?? ""}` : "https://github.com/helix-editor/helix/wiki/Language-Server-Configurations",
    licenses: profile.provenance?.source === "Zed" ? [] : ["MPL-2.0"],
    source: { id: "" },
    executables: profile.launch.kind === "native" ? [profile.launch.command] : []
  }))
];

